/* Splash POPAIS Food */
(function(){
  var css = `#splash{--logo:url(data:image/png;base64,);position:fixed;inset:0;z-index:99999;background:#E1B23E;display:flex;flex-direction:column;align-items:center;justify-content:center;transition:opacity .55s ease,visibility .55s ease}
#splash.hide{opacity:0;visibility:hidden}
#splash .logo{position:relative;width:min(78vw,380px);aspect-ratio:560/304;background:var(--logo) center/contain no-repeat;opacity:0;transform:scale(.6);animation:logoIn .95s cubic-bezier(.2,.9,.3,1.25) .15s forwards;filter:drop-shadow(0 10px 18px rgba(74,28,8,.28))}
#splash .logo::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 38%,rgba(255,255,255,.7) 50%,transparent 62%) 160% 0/250% 100% no-repeat;-webkit-mask:var(--logo) center/contain no-repeat;mask:var(--logo) center/contain no-repeat;animation:shine 1.1s ease 1.1s forwards}
#splash .bar{position:absolute;bottom:14%;width:min(46vw,190px);height:4px;border-radius:4px;background:rgba(74,28,8,.18);overflow:hidden;opacity:0;animation:fade .4s ease .9s forwards}
#splash .bar i{display:block;height:100%;width:100%;background:#4A1C08;border-radius:4px;transform:translateX(-100%);animation:load 1.9s cubic-bezier(.4,0,.2,1) 1s forwards}
@keyframes logoIn{0%{opacity:0;transform:scale(.6)}60%{opacity:1}100%{opacity:1;transform:scale(1)}}
@keyframes shine{to{background-position:-60% 0}}
@keyframes fade{to{opacity:1}}
@keyframes load{to{transform:translateX(0)}}
@media (prefers-reduced-motion:reduce){#splash *,#splash *::after{animation-duration:.01s!important;animation-delay:0s!important}}`;
  var st = document.createElement('style');
  st.textContent = css;
  document.head.appendChild(st);
  var box = document.createElement('div');
  box.innerHTML = `<div id="splash">
  <div class="logo" role="img" aria-label="Popais Food"></div>
  <div class="bar"><i></i></div>
</div>`;
  var s = box.firstElementChild;
  document.body.insertBefore(s, document.body.firstChild);
  var inicio = Date.now(), minimo = 2900;
  function fechar(){
    var resta = Math.max(0, minimo - (Date.now() - inicio));
    setTimeout(function(){
      s.classList.add('hide');
      setTimeout(function(){ s.remove(); }, 700);
    }, resta);
  }
  if (document.readyState === 'complete') fechar();
  else window.addEventListener('load', fechar);
})();
